describe('REQ-SYNC-002 upsert by id', () => {
  it('REQ-SYNC-002 inserts new ids as received (from peer) or sent (from me, another device)', () => {
    const fromBob = wire({ from: 'Bob', to: 'Alice' })
    const fromMe = wire({ from: 'Alice', to: 'Carol' })
    const { messages } = mergeSync({ messages: [], outbox: [] }, [fromBob, fromMe], 'Alice')
    expect(messages.find((m) => m.id === fromBob.id)?.status).toBe('received')
    expect(messages.find((m) => m.id === fromMe.id)?.status).toBe('sent')
  })

  it('REQ-SYNC-002 a queued outbox entry whose acknowledgement was lost becomes sent and leaves the outbox', () => {
    const q1 = local()
    const q2 = local()
    const server = wire({ ...q1, seq: 4, receivedAt: '2026-10-15T10:00:02.000Z', extra: 'ignored' } as never)
    const next = mergeSync({ messages: [q1, q2], outbox: [q1.id, q2.id] }, [server], 'Alice')
    expect(next.outbox).toEqual([q2.id])
    expect(next.messages).toHaveLength(2)
    const merged = next.messages.find((m) => m.id === q1.id)
    expect(merged).toEqual({ ...q1, seq: 4, receivedAt: '2026-10-15T10:00:02.000Z', status: 'sent', errorCode: null })
    // REQ-PROTO-004: unknown fields are ignored.
    expect(merged).not.toHaveProperty('extra')
  })

  it('REQ-SYNC-002 REQ-SYNC-003 merging is idempotent', () => {
    const w = wire()
    const once = mergeSync({ messages: [], outbox: [] }, [w], 'Alice')
    const twice = mergeSync(once, [w], 'Alice')
    expect(twice).toEqual(once)
  })

  it('REQ-SYNC-005 a local failed message wins; the server copy is not stored', () => {
    const failed = local({ status: 'failed', errorCode: 'id_conflict' })
    const other = wire()
    const server = wire({ id: failed.id, from: 'Mallory', to: 'Alice', body: 'different' })
    const next = mergeSync({ messages: [failed], outbox: [] }, [server, other], 'Alice')
    expect(next.messages).toHaveLength(2)
    expect(next.messages.find((m) => m.id === failed.id)).toBe(failed)
    expect(next.messages.find((m) => m.id === other.id)?.status).toBe('received')
  })
})

